changeSet.sql:

CREATE TABLE chat_users(
    chat_id INTEGER REFERENCES chats(id) ON UPDATE CASCADE ON DELETE CASCADE,
    user_id INTEGER REFERENCES users(id) ON UPDATE CASCADE ON DELETE CASCADE,
    PRIMARY KEY(chat_id, user_id)
);


ALTER TABLE admins ENABLE ROW LEVEL SECURITY;
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE chats ENABLE ROW LEVEL SECURITY;
ALTER TABLE chat_users ENABLE ROW LEVEL SECURITY;
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;

CREATE POLICY backend_full_access_admins ON admins FOR ALL USING (true);
CREATE POLICY backend_full_access_users ON users FOR ALL USING (true);
CREATE POLICY backend_full_access_chats ON chats FOR ALL USING (true);
CREATE POLICY backend_full_access_chat_users ON chat_users FOR ALL USING (true);
CREATE POLICY backend_full_access_messages ON messages FOR ALL USING (true);
